using RabbitMQ.Client;
using System.Text;

var factory = new ConnectionFactory()
{
    HostName = "localhost",
    UserName = "guest",
    Password = "guest"
};

using var connection = factory.CreateConnection();
using var channel = connection.CreateModel();

channel.ExchangeDeclare("orders", ExchangeType.Direct);
channel.QueueDeclare("order-processing", durable: true, exclusive: false, autoDelete: false, null);
channel.QueueBind("order-processing", "orders", "order.created");

var body = Encoding.UTF8.GetBytes("{\"orderId\": 101}");
channel.BasicPublish(exchange: "orders", routingKey: "order.created", basicProperties: null, body: body);

Console.WriteLine("Message published to orders exchange");
